[예시 1 · 출력]
{
 "rules": [
  {
   "rule_id": "R-EX-01",
   "status": "OK",
   "label": "가입 대상 명의 유형",
   "source": {
    "quote": "법인과 공동명의 계좌는 가입할 수 없습니다"
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "customer.holder_type"
      },
      [
       "INDIVIDUAL",
       "SOLE_PROPRIETOR",
       "ORGANIZATION"
      ]
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

