      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "SALARY_TRANSFER",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "ATM_WITHDRAW_AFTER_HOURS",
    "value": "UNLIMITED"
   }
  },
  {
   "rule_id": "R-EX-02-03",
   "status": "OK",
   "label": "자동화기기 이체수수료 면제",
   "source": {
    "quote": "자동화기기 이체수수료 | 월 10회"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "exists": {
     "event": "SALARY_TRANSFER",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "FEE_WAIVE",
    "target": "ATM_TRANSFER",
    "value": 10
   }
  }
 ]
}

[예시 3 · 조문]
[한도 예외]
▪ 가입금액이 500만원 이상인 경우 이체한도를 2천만원으로 한다.
▪ “영업점장”이 필요하다고 인정하는 경우 한도를 달리 정할 수 있습니다.
※ 이 경우의 한도는 영업점에 고시한 바에 따릅니다.
[예시 3 · 출력]
{
 "rules": [
  {
   "rule_id": "R-EX-99-01",
   "status": "OK",
   "label": "가입금액에 따른 이체한도",
   "source": {
    "quote": "▪ 가입금액이 500만원 이상인 경우 이체한도를 2천만원으로 한다."
   },
   "condition": {
    ">=": [
     {
      "var": "contract.amount"
     },
